//
// 16.16 fixed-point multiply as a VexRiscv custom instruction (CfuPlugin)
//
// CPU side as generated by LiteX's VexRiscv_FullCfu.v (CfuPlugin stageCount = 1,
// allowZeroLatency = true, CFU_FUNCTION_ID_W = 10, two 32-bit inputs, one output):
// the command leaves the CPU with the instruction in the execute stage and the
// result has to be there when the instruction reaches the memory stage, one clock
// later. A result registered at the end of the command's clock is in time, so the
// instruction costs one cycle like an add (plus one stall if the very next
// instruction uses the result, as after a load).
//
// Instruction: R-type, opcode custom-0 (0001011), function_id = {funct7, funct3}
//   rd = (rs1 * rs2) >> 16, both signed 16.16, result rounded toward -infinity
//   (the same as (int32_t)(((int64_t)a * b) >> 16) in C)
//
module cfu_fixmul (
    input  wire         clk,
    input  wire         reset,

    input  wire         cmd_valid,
    output wire         cmd_ready,
    input  wire [9:0]   cmd_payload_function_id,
    input  wire [31:0]  cmd_payload_inputs_0,      // rs1
    input  wire [31:0]  cmd_payload_inputs_1,      // rs2

    output reg          rsp_valid,
    input  wire         rsp_ready,
    output reg  [31:0]  rsp_payload_outputs_0      // rd
);

    // take a command whenever the result register is empty or being emptied this clock
    assign cmd_ready = ~rsp_valid | rsp_ready;
    wire fire = cmd_valid & cmd_ready;

    wire signed [63:0] product = $signed(cmd_payload_inputs_0) * $signed(cmd_payload_inputs_1);

always @(posedge clk) begin
    if(reset)           rsp_valid <= 1'b0;
    else if(cmd_ready)  rsp_valid <= cmd_valid;
    if(fire)            rsp_payload_outputs_0 <= product[47:16];
end

endmodule
